--
-- Table structure for table `tg_leads_recorder`
--

DROP TABLE IF EXISTS `tg_leads_recorder`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tg_leads_recorder` (
  `leadId` bigint NOT NULL AUTO_INCREMENT,
  `contactId` bigint DEFAULT NULL,
  `leadSource` int DEFAULT NULL,
  `adults` int DEFAULT NULL,
  `children` int DEFAULT NULL,
  `childrenAgeInfo` varchar(145) DEFAULT NULL,
  `tentativeCost` int DEFAULT NULL,
  `clientRemarks` varchar(2500) DEFAULT NULL,
  `internalRemarks` varchar(1500) DEFAULT NULL,
  `source` bigint DEFAULT NULL,
  `destination` bigint DEFAULT NULL,
  `travelStartDate` date DEFAULT NULL,
  `travelEndDate` date DEFAULT NULL,
  `leadStatus` int DEFAULT NULL,
  `resultReason` int DEFAULT NULL,
  `isQualified` tinyint DEFAULT NULL,
  `isFlagged` tinyint DEFAULT NULL,
  `leadOwner` int DEFAULT NULL,
  `landPackage` tinyint DEFAULT NULL,
  `flight` tinyint DEFAULT NULL,
  `hotel` tinyint DEFAULT NULL,
  `transfers` tinyint DEFAULT NULL,
  `sightseeing` tinyint DEFAULT NULL,
  `visa` tinyint DEFAULT NULL,
  `insurance` tinyint DEFAULT NULL,
  `cruise` tinyint DEFAULT NULL,
  `others` tinyint DEFAULT NULL,
  `leadCreationClientInformed` tinyint DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `leadName` varchar(255) DEFAULT NULL,
  `remarks` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`leadId`),
  KEY `FK_SRC_idx` (`source`,`destination`),
  KEY `FK_DST_idx` (`destination`),
  CONSTRAINT `FK_DST` FOREIGN KEY (`destination`) REFERENCES `udndestinations` (`destinationId`),
  CONSTRAINT `FK_SRC` FOREIGN KEY (`source`) REFERENCES `udndestinations` (`destinationId`)
) ENGINE=InnoDB AUTO_INCREMENT=1022 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='This is the main table for lead management. ';
/*!40101 SET character_set_client = @saved_cs_client */;

