DROP TABLE IF EXISTS `tg_supplier_contacts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tg_supplier_contacts` (
  `supplierContactId` bigint NOT NULL AUTO_INCREMENT,
  `supplierId` bigint DEFAULT NULL,
  `contactName` varchar(145) DEFAULT NULL,
  `mobile` bigint DEFAULT NULL,
  `phone` bigint DEFAULT NULL,
  `email` varchar(245) DEFAULT NULL,
  `description` varchar(200) DEFAULT NULL,
  `role` varchar(200) DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `deleted` tinyint DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `lastUpdatedBy` int DEFAULT NULL,
  PRIMARY KEY (`supplierContactId`),
  KEY `FK_CNT_SUPP_idx` (`supplierId`),
  KEY `FK_CNT_CITY_idx` (`city`),
  KEY `FK_CNT_LST_USR_idx` (`lastUpdatedBy`),
  CONSTRAINT `FK_CNT_LST_USR` FOREIGN KEY (`lastUpdatedBy`) REFERENCES `udnteam` (`userId`),
  CONSTRAINT `FK_CNT_SUPP` FOREIGN KEY (`supplierId`) REFERENCES `tg_supplier_master` (`supplierId`)
) ENGINE=InnoDB AUTO_INCREMENT=291 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

