  `cruiseSeperateCostDisplay` tinyint DEFAULT '0',
  `cruiseGstBreakup` tinyint DEFAULT '0',
  `cruiseCancellationPolicyDisplay` tinyint DEFAULT '0',
  `cruiseCancellationPolicy` varchar(1000) DEFAULT NULL,
  `packageSeperateCostDisplay` tinyint DEFAULT '0',
