--
-- Table structure for table `udn_deals_recorder`
--

DROP TABLE IF EXISTS `udn_deals_recorder`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `udn_deals_recorder` (
  `dealConfirmationId` bigint NOT NULL AUTO_INCREMENT,
  `queryId` bigint DEFAULT NULL,
  `clientId` bigint NOT NULL,
  `adults` int DEFAULT NULL,
  `children` int DEFAULT NULL,
  `travelStartDate` date NOT NULL,
  `travelEndDate` date NOT NULL,
  `travelingFrom` bigint NOT NULL,
  `travelingTo` bigint NOT NULL,
  `dealDescription` varchar(300) DEFAULT NULL,
  `dealSource` int NOT NULL,
  `isNewClient` tinyint NOT NULL COMMENT 'Deal Business Type classifies , if the entered deal is for new client or for repeated client. ',
  `isClientInformed` tinyint NOT NULL COMMENT 'if the creation of the deal information is sent to the client or not. ',
  `projectedCost` float DEFAULT NULL,
  `sellingPrice` float DEFAULT NULL,
  `actualCost` float DEFAULT NULL,
  `dealStatus` int NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `dealOwner` int DEFAULT NULL,
  `bookingDate` datetime DEFAULT NULL,
  `isActive` tinyint NOT NULL DEFAULT '1',
  PRIMARY KEY (`dealConfirmationId`),
  KEY `FK_TRV_FRM_idx` (`travelingFrom`),
  KEY `FK_TRV_TO_idx` (`travelingTo`),
  KEY `FK_CLIENTID_idx` (`clientId`),
  KEY `FK_DO_USER_idx` (`dealOwner`),
  CONSTRAINT `FK_CLIENTID` FOREIGN KEY (`clientId`) REFERENCES `udnclients` (`clientId`),
  CONSTRAINT `FK_DO_USR_TEAM` FOREIGN KEY (`dealOwner`) REFERENCES `udnteam` (`userId`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_TRV_FRM` FOREIGN KEY (`travelingFrom`) REFERENCES `udndestinations` (`destinationId`),
  CONSTRAINT `FK_TRV_TO` FOREIGN KEY (`travelingTo`) REFERENCES `udndestinations` (`destinationId`)
) ENGINE=InnoDB AUTO_INCREMENT=326 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='This is the base deal table at a super high level and provides high level information about the deal. ';
/*!40101 SET character_set_client = @saved_cs_client */;

