--
-- Table structure for table `udn_flt_manual_quotation`
--

DROP TABLE IF EXISTS `udn_flt_manual_quotation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `udn_flt_manual_quotation` (
  `manualFlightQuotationId` bigint NOT NULL AUTO_INCREMENT,
  `quotationId` bigint DEFAULT NULL,
  `airlineId` int DEFAULT NULL,
  `flightNumber` varchar(55) DEFAULT NULL,
  `airportCodeOrigin` int DEFAULT NULL,
  `airportCodeDestination` int DEFAULT NULL,
  `departureDate` datetime DEFAULT NULL,
  `arrivalDate` datetime DEFAULT NULL,
  `duration` varchar(100) DEFAULT NULL,
  `adultCount` int DEFAULT NULL,
  `childCount` int DEFAULT NULL,
  `infantCount` int DEFAULT NULL,
  `noOfStops` int DEFAULT NULL,
  `cabinClass` int DEFAULT NULL,
  `flightCost` int DEFAULT NULL,
  `flightMarkup` int DEFAULT NULL,
  `displayOrder` int DEFAULT NULL,
  `active` tinyint DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`manualFlightQuotationId`),
  KEY `FK_QTN_ID_idx` (`quotationId`),
  KEY `FK_ARLINE_idx` (`airlineId`),
  KEY `FK_APT_ORIGIN_idx` (`airportCodeOrigin`),
  KEY `FK_APT_DEST_idx` (`airportCodeDestination`),
  CONSTRAINT `FK_APT_DEST` FOREIGN KEY (`airportCodeDestination`) REFERENCES `tg_flt_airport_details` (`airportId`),
  CONSTRAINT `FK_APT_ORIGIN` FOREIGN KEY (`airportCodeOrigin`) REFERENCES `tg_flt_airport_details` (`airportId`),
  CONSTRAINT `FK_ARLINE` FOREIGN KEY (`airlineId`) REFERENCES `udn_airline_master` (`airlineId`),
  CONSTRAINT `FK_QTN_ID` FOREIGN KEY (`quotationId`) REFERENCES `tg_quotations_recorder` (`quotationId`)
) ENGINE=InnoDB AUTO_INCREMENT=1491 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

