--
-- Table structure for table `udn_flt_service_line`
--

DROP TABLE IF EXISTS `udn_flt_service_line`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `udn_flt_service_line` (
  `fltServiceId` bigint NOT NULL AUTO_INCREMENT,
  `serviceMapId` bigint NOT NULL,
  `dealConfirmationId` bigint DEFAULT NULL,
  `airlineId` int NOT NULL,
  `departureDate` datetime NOT NULL,
  `arrivalDate` datetime NOT NULL,
  `departingFrom` int DEFAULT NULL,
  `arrivingTo` int DEFAULT NULL,
  `flightNumber` varchar(45) DEFAULT NULL,
  `adults` int DEFAULT NULL,
  `children` int DEFAULT NULL,
  `infants` int DEFAULT NULL,
  `cabinClass` int DEFAULT '1',
  `supplierId` int NOT NULL,
  `noofhalt` int DEFAULT NULL,
  `remarks` varchar(145) DEFAULT NULL,
  `serviceLineCost` float DEFAULT NULL,
  `markup` float DEFAULT '0',
  `status` int NOT NULL,
  `displayOrder` int DEFAULT '0',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`fltServiceId`),
  KEY `FK_SRV_MAP_idx` (`serviceMapId`),
  KEY `FK_DEAL_ID_idx` (`dealConfirmationId`),
  CONSTRAINT `FK_DEAL_ID` FOREIGN KEY (`dealConfirmationId`) REFERENCES `udn_deals_recorder` (`dealConfirmationId`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_SRV_MAP` FOREIGN KEY (`serviceMapId`) REFERENCES `udn_deal_service_map` (`serviceMapId`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=216 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

