--
-- Table structure for table `udn_htl_manual_quotation`
--

DROP TABLE IF EXISTS `udn_htl_manual_quotation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `udn_htl_manual_quotation` (
  `manualHotelQuotationId` bigint NOT NULL AUTO_INCREMENT,
  `quotationId` bigint DEFAULT NULL,
  `optionNo` int DEFAULT NULL,
  `hotelId` int NOT NULL,
  `roomCategoryId` int DEFAULT '0',
  `cityId` int DEFAULT NULL,
  `checkInDate` date NOT NULL,
  `checkOutDate` date NOT NULL,
  `adults` int NOT NULL,
  `children` int NOT NULL,
  `extrabed` int NOT NULL,
  `mealPlan` int NOT NULL,
  `noOfRooms` int DEFAULT '1',
  `remarks` varchar(1500) DEFAULT NULL,
  `hotelStayCost` int DEFAULT '0',
  `hotelStayMarkup` int DEFAULT '0',
  `displayOrder` int DEFAULT NULL,
  `active` tinyint DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`manualHotelQuotationId`),
  KEY `FK_HTL_ID_idx` (`hotelId`),
  KEY `FK_RM_CAT_QTN_idx` (`roomCategoryId`),
  KEY `FK_HTL_QTN_ID_idx` (`quotationId`),
  CONSTRAINT `FK_HTL_ID_QTN` FOREIGN KEY (`hotelId`) REFERENCES `udn_hotel_master` (`hotelId`),
  CONSTRAINT `FK_HTL_QTN_ID` FOREIGN KEY (`quotationId`) REFERENCES `tg_quotations_recorder` (`quotationId`),
  CONSTRAINT `FK_RM_CAT_QTN` FOREIGN KEY (`roomCategoryId`) REFERENCES `udn_room_category_master` (`roomCategoryId`)
) ENGINE=InnoDB AUTO_INCREMENT=2473 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

