--
-- Table structure for table `udn_htl_service_line`
--

DROP TABLE IF EXISTS `udn_htl_service_line`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `udn_htl_service_line` (
  `htlServiceId` bigint NOT NULL AUTO_INCREMENT,
  `hotelId` int NOT NULL,
  `roomCategoryId` int DEFAULT '0',
  `cityId` int DEFAULT NULL,
  `dealConfirmationId` bigint DEFAULT NULL,
  `serviceMapId` bigint NOT NULL,
  `checkInDate` date NOT NULL,
  `checkOutDate` date NOT NULL,
  `supplierId` bigint NOT NULL,
  `holdingDate` date DEFAULT NULL,
  `adults` int NOT NULL,
  `children` int NOT NULL,
  `extrabed` int NOT NULL DEFAULT '0',
  `mealplan` int NOT NULL DEFAULT '1',
  `noofrooms` int DEFAULT '1',
  `remarks` varchar(245) DEFAULT NULL,
  `status` int NOT NULL DEFAULT '0',
  `serviceLineCost` float DEFAULT '0',
  `markup` float DEFAULT '0',
  `displayOrder` int DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`htlServiceId`),
  KEY `FK_HTL_ID_idx` (`hotelId`),
  KEY `FK_SRV_MAP_idx` (`serviceMapId`),
  KEY `FK_HTL_SUPP_idx` (`supplierId`),
  KEY `FK_DEAL_ID_idx` (`dealConfirmationId`),
  CONSTRAINT `FK_CSC_HTL_DEAL_C` FOREIGN KEY (`dealConfirmationId`) REFERENCES `udn_deals_recorder` (`dealConfirmationId`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_HTL_ID` FOREIGN KEY (`hotelId`) REFERENCES `udn_hotel_master` (`hotelId`),
  CONSTRAINT `FK_HTL_SRV_MAP` FOREIGN KEY (`serviceMapId`) REFERENCES `udn_deal_service_map` (`serviceMapId`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_HTL_SUPP` FOREIGN KEY (`supplierId`) REFERENCES `tg_supplier_master` (`supplierId`)
) ENGINE=InnoDB AUTO_INCREMENT=173 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

