INSERT INTO `udn_ticket_recorder` VALUES (39,'Refund from Airline Mrs. Bimla One Way- AO 193267083','Airlines confirmed to client about the one way refund as flight was cancelled. RA was raised but needs to be followed up with airline. Ticket is created to track it unless closure. ','Medium',0,227,1,1,'2020-12-10 23:41:00','Open','2020-11-06 18:11:39','2020-11-06 18:11:39'),(40,'Mr. Bimal Bhalla - Rescheduling of Air Asia Indore Delhi Flight','			Air Asia Airlines Changed the return flight from 2nd Dec to 3rd December but Guest is more comfortable returning back on 1st Dec 2020 but dont want 3rd December. Please take this up with airline and coordinate the best possible outcome. \r\n		','Medium',0,228,1,1,'2020-11-20 07:32:00','Closed','2020-11-18 02:04:32','2020-11-19 04:14:21'),(41,'Mr. HARI PRAKASH  +1 - Air India Flight Rescheduling Approaching','			23/3/21: Partial Amount refunded. 1 Lack balance pending. \r\n12/9/2020 11:10:16 AM	Nikhil Marwah	4000565801//4000565805\r\n		','High',0,229,1,1,'2020-12-31 18:00:00','Closed','2020-12-05 14:40:25','2021-06-21 15:55:18'),(42,'Track Refund for - HN2IQN','			There were two tickets and the refund is not traceable for the PNR HN2IQN. We are investigating this issue and will revert back soon on the same. \r\n\r\n		','High',0,239,103,1,'2021-04-10 08:48:00','Closed','2021-04-02 03:19:59','2021-06-21 15:55:02'),(43,'Ticket Refund','hello test 123','High',15569,0,1,1,'2024-01-08 19:00:00','Closed','2024-01-08 10:03:51','2024-02-08 02:49:38'),(44,'Full Refund Due to Changes in Flight Details (PNR: [KZ5BPG])',NULL,'High',5,0,17297,17297,'2024-03-12 15:47:00','Open','2024-03-04 10:20:26','2024-03-04 10:20:26');
