CREATE TABLE `udn_trn_service_line` (
  `trnServiceId` bigint NOT NULL AUTO_INCREMENT,
  `pickupCityId` bigint DEFAULT NULL,
  `dropCityId` bigint DEFAULT NULL,
  `dealConfirmationId` bigint DEFAULT NULL,
  `serviceMapId` bigint DEFAULT NULL,
  `transferDate` date DEFAULT NULL,
  `supplierId` bigint DEFAULT NULL,
  `adults` int DEFAULT NULL,
  `children` int DEFAULT NULL,
  `infants` int DEFAULT NULL,
  `transferType` int DEFAULT NULL,
  `pickUpFrom` int DEFAULT NULL,
  `pickUpFromName` varchar(145) DEFAULT NULL,
  `dropTo` int DEFAULT NULL,
  `dropToName` varchar(145) DEFAULT NULL,
  `remarks` varchar(250) DEFAULT NULL,
  `serviceLineCost` float DEFAULT NULL,
  `markup` float DEFAULT NULL,
  `status` int DEFAULT NULL,
  `displayOrder` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`trnServiceId`),
  KEY `FK_TRN_CITY_idx` (`pickupCityId`),
  KEY `FK_TRN_SRV_MAP_idx` (`serviceMapId`),
  KEY `FK_TRN_SUPP_idx` (`supplierId`),
  KEY `FK_TRN_STATUS_idx` (`status`),
  KEY `FK_TRN_DEAL_CNF_idx` (`dealConfirmationId`),
  CONSTRAINT `FK_TRN_CITY` FOREIGN KEY (`pickupCityId`) REFERENCES `udndestinations` (`destinationId`),
  CONSTRAINT `FK_TRN_DEAL_CNF` FOREIGN KEY (`dealConfirmationId`) REFERENCES `udn_deals_recorder` (`dealConfirmationId`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_TRN_SRV_MAP` FOREIGN KEY (`serviceMapId`) REFERENCES `udn_deal_service_map` (`serviceMapId`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_TRN_STATUS` FOREIGN KEY (`status`) REFERENCES `udn_deal_status` (`id`),
  CONSTRAINT `FK_TRN_SUPP` FOREIGN KEY (`supplierId`) REFERENCES `tg_supplier_master` (`supplierId`)
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
